package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Validate sort parameter against whitelist
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortBy == "" || !allowedSorts[sortBy] {
		sortBy = "id"
	}

	// Build query - category is parameterized, min_price is validated as numeric
	baseQuery := "SELECT id, name, price, sku FROM products WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if category != "" {
		baseQuery += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	if minPrice != "" {
		// Developer assumed this would be validated by frontend
		baseQuery += " AND price >= " + minPrice
	}

	baseQuery += " ORDER BY " + sortBy + " LIMIT 50"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// getProductDetail returns a single product - properly parameterized
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	var p Product
	err := db.QueryRow("SELECT id, name, price, sku FROM products WHERE id = $1", id).Scan(&p.ID, &p.Name, &p.Price, &p.SKU)
	if err != nil {
		http.Error(w, "Not found", 404)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

// healthCheck for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func loggingMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// Log request for audit - note: does not sanitize
		log.Printf("%s %s %s query=%s", r.RemoteAddr, r.Method, r.URL.Path, r.URL.RawQuery)
		// Block requests with suspicious path traversal
		if strings.Contains(r.URL.Path, "..") {
			http.Error(w, "Forbidden", 403)
			return
		}
		next(w, r)
	}
}

func main() {
	http.HandleFunc("/api/products/search", loggingMiddleware(searchProducts))
	http.HandleFunc("/api/products/detail", loggingMiddleware(getProductDetail))
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
